namespace("rt-thread", function()

rule("common")
    add_deps("xhive.embed")
    on_load(function(target)
        local sdir = os.scriptdir()
        target:add("includedirs", path.join(sdir, "include"), {public=true})
    end)
    before_build(function(target)
        import("core.cache.memcache")
        import("xhive.base")
        import("xhive.kconf")
        local dirs = base.load_paths()
        local sdir = os.scriptdir()

        if memcache.get("xhive", "rtconfig_built") then
            return
        end
        memcache.set("xhive", "rtconfig_built", true)

        local kconfig_entry = path.join(sdir, "Kconfig")
        local header_path   = path.join(dirs.builddir, "rtconfig.h")

        if os.exists(header_path) then
            os.rm(header_path)
        end
        kconf.build_header_with_entry(header_path, kconfig_entry)

        -- read header file, remove all "CONFIG_" prefix, add include guards, write back
        local file = io.readfile(header_path)
        file = file:gsub(" CONFIG_", " ")
        file = "// Auto Generated by xhive, do not edit!\n\n"..
               "#ifndef __RT_CONFIG_H__\n"..
               "#define __RT_CONFIG_H__\n\n"..
               file.. "\n"..
               "#endif /* __RT_CONFIG_H__ */\n"
        io.writefile(header_path, file)
    end)
rule_end()
add_rules("common")

includes("src")
includes("libcpu")
includes("components")

target("deps")
    set_kind("object")
    set_default(false)

    add_deps("src", {public=true})
    add_deps("libcpu", {public=true})
    add_deps("components", {public=true})
    
    on_load(function(target)
        import("xhive.base")
        local conf = target:data("kconfig") or {}
        if conf.RT_USING_SMART then
            raise("Not support RT_USING_SMART yet!")
        end
    end)
target_end()

end) -- namespace rt-thread


